(article?){kim_climate_2022, title = {Climate change impact on water supply and hydropower generation potential in {Northern} {Manitoba}}, volume = {41}, issn = {2214-5818}, url = {https://www.sciencedirect.com/science/article/pii/S2214581822000908}, doi = {10.1016/j.ejrh.2022.101077}, abstract = {Study region: Lower Nelson River Basin, Manitoba, Canada. Study focus: Hydroelectricity makes up almost 97% of electricity generated in Manitoba, of which over 70% of its generation capacity is installed along the Lower Nelson River (LNR). In this study, 19 climate projections representing {} 87% of climatic variability over Hudson Bay Drainage Basin are applied to coupled hydrologic-operations models to estimate water supply and hydropower generation potential changes under future climates. New hydrological insights for the region: Future inflow to the forebay of the main hydropower generating stations along LNR is expected to increase in spring and summer but decrease in winter and fall. Consequently, hydropower generation potential is projected to increase for spring, the historical flood season, which may lead to reduced reservoir inflow retention efficiency. In extremely dry climatic simulations, winter seasons see a reduction in reservoir inflow and hydropower generation potential, up to 35% and 37% in 2021–2050 and 2041–2070, respectively. Projected changes in reservoir inflow and hydropower generation potential continue to diverge over time, with dry scenarios becoming drier and wet becoming wetter, yielding high basin climate sensitivity and uncertainty with system supply and generation potential. Despite the presence of statistically significant individual trends and changes, there is a low agreement within the climate ensemble. Analysis of system robustness shows adjustment of the operations along LNR should be considered over time to better leverage changing seasonal water supply.}, urldate = {2025-06-27}, journal = {Journal of Hydrology: Regional Studies}, author = {Kim, Su Jin and Asadzadeh, Masoud and Stadnyk, Tricia A.}, month = jun, year = {2022}, keywords = {Climate change, Cascade river-reservoir system, Hydrologic modeling, Hydropower, Model coupling, Operations modeling}, pages = {101077}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\JW4T4JXK\S2214581822000908.html:text/html}, }
(article?){haguma_optimal_2014, title = {Optimal {Hydropower} {Generation} {Under} {Climate} {Change} {Conditions} for a {Northern} {Water} {Resources} {System}}, volume = {28}, issn = {1573-1650}, url = {https://doi.org/10.1007/s11269-014-0763-3}, doi = {10.1007/s11269-014-0763-3}, abstract = {This paper examines climate change impacts on the water resources system of the Manicouagan River (Québec, Canada). The objective is to evaluate the performance of existing infrastructures under future climate projections and the associated uncertainties. The main purpose of the water resources system is hydropower production. A reservoir optimization algorithm, Sampling Stochastic Dynamic Programming (SSDP), was used to derive weekly operating decisions for the existing system subject to reservoir inflows reflecting future climate, for optimum hydropower production. These projections are simulations from the SWAT hydrologic model for climate change scenarios for the period from 2010 to 2099. Results show that the climate change will alter the hydrological regime of the study area: earlier timing of the spring flood, reduced spring peak flow, and increased annual inflows volume in the future compared to the historical climate. The SSDP optimization algorithm adapted the operating policy to the future hydrological regime by adjusting water reservoir levels in the winter and spring, and increasing the release through turbines, which in the end increased power generation. However, there could be more unproductive spills for some power plants, which would decrease the overall efficiency of the existing water resources system.}, language = {en}, number = {13}, urldate = {2025-07-02}, journal = {Water Resources Management}, author = {Haguma, Didier and Leconte, Robert and Côté, Pascal and Krau, Stéphane and Brissette, François}, month = oct, year = {2014}, keywords = {Climate change, Climate-Change Adaptation, Drought, Hydroenergy, Hydrologic regime, Operating policy, Renewable Energy, Water Industry and Water Technology, Water Policy, Water resources system}, pages = {4631–4644}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\24I8HDX3\Haguma et al. - 2014 - Optimal Hydropower Generation Under Climate Change.pdf:application/pdf}, }
(article?){parkinson_robust_2015, title = {Robust response to hydro-climatic change in electricity generation planning}, volume = {130}, url = {https://ideas.repec.org//a/spr/climat/v130y2015i4p475-489.html}, abstract = {An electricity generation planning framework incorporating adaptation to hydro-climatic change is presented. The planning framework internalizes risks and opportunities associated with alternative hydro-climate scenarios to identify a long-term system configuration robust to uncertainty. The implications of a robust response to hydro-climatic change are demonstrated for the electricity system in British Columbia (BC), Canada. Adaptation strategy is crucial in this region, mainly due to the large contribution of hydropower resources to regional electricity supply. Analysis of results from basin-scale hydrologic models driven with downscaled global climate data suggest that shifts in regional streamflow characteristics by the year 2050 are likely to increase BC’s annual hydropower potential by more than 10 %. These effects combined with an estimated decrease in electricity demand by 2 % due to warmer temperatures, could provide an additional 11 TWh of annual energy. Uncertainties in these projected climate impacts indicate technology configurations offering significant long-term operational flexibility will be needed to ensure system reliability. Results from the regional long-term electricity generation model incorporating adaptive capacity show the significant shifts required in the non-hydro capacity mix to ensure system robustness cause an increase in cumulative operating costs of between 1 and 7 %. Analysis of technology configurations involving high-penetrations of wind generation highlights interactions between flexibility requirements occurring over multiple temporal scales. Copyright Springer Science+Business Media Dordrecht 2015}, language = {en}, number = {4}, urldate = {2025-07-02}, journal = {Climatic Change}, author = {Parkinson, Simon and Djilali, Ned}, year = {2015}, note = {Publisher: Springer}, pages = {475–489}, file = {Snapshot:C:\Users\sheikm33\Zotero\storage\5ZKVG3PK\v130y2015i4p475-489.html:text/html}, }
(article?){li_impact_2023, title = {Impact of climate change on wind energy across {North} {America} under climate change scenario {RCP8}.5}, volume = {288}, issn = {0169-8095}, url = {https://www.sciencedirect.com/science/article/pii/S0169809523001199}, doi = {10.1016/j.atmosres.2023.106722}, abstract = {Wind energy is one of the renewable energies considered by many nations as a strategy to mitigate the impact of climate change. There are also impacts of climate change on wind energy. Previous studies investigated the effect of climate change on wind energy in North America by using future projections with spatial resolutions of about 100 km (i.e., around 1° × 1° simulation grid) and monthly to yearly average wind speeds or a high spatial resolution ({} 50 km) but a few simulations ({} 5). A coarse resolution can create biases and is insufficient to appreciate extremes. A smaller number of simulations (e.g., {} 5) are inadequate for understanding the modeling uncertainties. To better appreciate the impact of climate change on wind energies in a future changing climate, 15 simulations from high-resolution Reginal Climate Models (RCMs) considering the Representative Concentration Pathway (RCP) 8.5 emission scenario were used in the present study. These datasets have a spatial resolution of about 0.4° and a temporal resolution of one hour from 1950 to 2100. The impact of climate change on wind energy was studied on a seasonal and yearly basis. The impact of climate change on design-level wind speeds and structural reliability across North America was also investigated.}, urldate = {2025-07-02}, journal = {Atmospheric Research}, author = {Li, Si Han}, month = jun, year = {2023}, keywords = {Climate change, Model uncertainty, Design wind speed, North America, Structrual reliability, Wind energy}, pages = {106722}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\WE7S7XL3\S0169809523001199.html:text/html}, }
(article?){yao_climate_2012, title = {Climate change impacts on {Ontario} wind power resource}, volume = {1}, issn = {2193-2697}, url = {https://doi.org/10.1186/2193-2697-1-2}, doi = {10.1186/2193-2697-1-2}, abstract = {The availability and reliability of wind power depend largely on current and future climate conditions, which may vary in the context of climate change. A high resolution regional climate model (PRECIS) was used for dynamic downscaling of the future wind speed over Ontario. The changes of wind power density and power production were further investigated through case studies.}, number = {1}, urldate = {2025-07-04}, journal = {Environmental Systems Research}, author = {Yao, Yao and Huang, Gordon H. and Lin, Qianguo}, month = aug, year = {2012}, keywords = {Climate change, Power production, Regional climate model, Wind speed}, pages = {2}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\KC3HGM4Z\Yao et al. - 2012 - Climate change impacts on Ontario wind power resou.pdf:application/pdf;Snapshot:C:\Users\sheikm33\Zotero\storage\CYSY6SZZ\2193-2697-1-2.html:text/html}, }
(misc?){cwtd_canadian_2022, title = {Canadian {Wind} {Turbine} {Database} - {Open} {Government} {Portal}}, url = {https://open.canada.ca/data/en/dataset/79fdad93-9025-49ad-ba16-c26d718cc070}, abstract = {The Canadian Wind Turbine Database contains the geographic location and key technology details for wind turbines installed in Canada. This dataset was jointly compiled by researchers at…}, language = {eng}, urldate = {2025-07-09}, author = {CWTD}, year = {2022}, file = {Snapshot:C:\Users\sheikm33\Zotero\storage\TKAS4QEQ\79fdad93-9025-49ad-ba16-c26d718cc070.html:text/html}, }
(article?){zhang_assessment_2022, title = {Assessment of climate change impacts on the hydro-wind-solar energy supply system}, volume = {162}, issn = {1364-0321}, url = {https://www.sciencedirect.com/science/article/pii/S1364032122003847}, doi = {10.1016/j.rser.2022.112480}, abstract = {Renewable energies such as hydro, wind, and solar power, are susceptible to the impacts of climate change. Energy Impact Assessment models under climate change are useful tools for understanding these impacts, but still face some challenges, such as the limited spatial resolution, the lack of utilization of the latest climate models, the inadequate analysis of uncertainties and extreme behaviors, and having not enough capability in simulating the coordinated operation of different power sources. To improve the situation, this study utilizes Random Forest Regression and its derivative Quantile Regression Forest to downscale the CMIP6 General Circulation Models for projecting the means and quantiles of the renewable energy resources for each individual power station under seven combined pathways of Shared Socioeconomic Pathways (SSPs) and Representative Concentration Pathways (RCPs). Based on the projected results, a coordinated operation strategy is established to quantify the impacts of climate change on the regional hydro-wind-solar energy supply system. The assessment reveals: (1) changes of hydro-meteorological variables will present spatially and seasonal inhomogeneous; (2) at the end of the century, the projected increased level of electricity supply will be the highest under the SSP5-RCP8.5 and the increment will be 8.680 TWh; (3) the extreme lack electricity supply will occur under the SSP3-RCP7.0 for the period 2041–2060 and the twenty-year average value will be reduced by 16.83 TWh relative to the historical period reference period.}, urldate = {2025-07-09}, journal = {Renewable and Sustainable Energy Reviews}, author = {Zhang, Yi and Cheng, Chuntian and Yang, Tiantian and Jin, Xiaoyu and Jia, Zebin and Shen, Jianjian and Wu, Xinyu}, month = jul, year = {2022}, keywords = {Climate change impacts, Extreme behaviors, High-precision projection, Hydro-wind-solar energy supply system, Quantile regression forest}, pages = {112480}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\XCKJPWD8\S1364032122003847.html:text/html}, }
(phdthesis?){lagace_assessing_2021, title = {Assessing the {Impact} of {Climate} {Change} on {Electricity} {Planning} in {Ontario}, {Canada}}, url = {http://hdl.handle.net/1807/109060}, abstract = {Electricity grid adequacy is the ability of the electric system to supply the electricity required at all times, accounting for derates and outages of system components. Ontario’s electricity needs are primarily met by thermal and hydroelectric generators, shown to be impacted by climate conditions. We quantify the effects of climate change on Ontario’s future demand and capacity based on the highest risk climate change scenario (RCP 8.5) for the year 2040. The main climate change variables considered are temperature, humidity, and precipitation. Very minor reductions in summer effective capacity are expected (approximately 0.2%), together with a moderate increase in summer demand (approximately 6%). These results only reflect the impacts of climate change relative to the current climate. Although the Independent Electricity System Operator appears to capture enough variability in their grid adequacy estimates, it may be wise to add additional butter to capture the impact of climate change discovered here.}, language = {en}, urldate = {2025-07-10}, author = {Lagace, Elise Emma}, month = nov, year = {2021}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\ME3EJ4FH\Lagace - 2021 - Assessing the Impact of Climate Change on Electric.pdf:application/pdf}, }
(article?){craig_compounding_2020, title = {Compounding climate change impacts during high stress periods for a high wind and solar power system in {Texas}}, volume = {15}, issn = {1748-9326}, url = {https://dx.doi.org/10.1088/1748-9326/ab6615}, doi = {10.1088/1748-9326/ab6615}, abstract = {Power system planning aims at ensuring that sufficient supply- and demand-side assets exist to meet electricity demand at all times. For a Texas electric power system with high wind and solar penetrations, we quantify how climate change will affect supply and demand during three types of high stress periods for the power grid: high demand hours, high net demand hours, and high system ramp hours. We specifically quantify effects on demand, reductions in available thermal capacity (i.e. thermal deratings), wind and solar generation, and net demand. We estimate each using meteorological variables from five climate change projections (2041–2050) assuming Representative Concentration Pathway 8.5 and from a reference period (1996–2005). All five projections indicate that climate change will increase demand by up to 2 GWh during high demand hours (4% of demand in the reference period) and increase net demand by up to 3 GWh during high net demand periods (6% of net demand in the reference period). All five projections also indicate thermal deratings will increase during high demand and net demand periods by up to 2 GWh and high net demand ramps will increase by up to 2 GW. Overall, our results indicate compounding effects of climate change in Texas will necessitate greater investment in peak and flexible capacity.}, language = {en}, number = {2}, urldate = {2025-07-10}, journal = {Environmental Research Letters}, author = {Craig, Michael T and Jaramillo, Paulina and Hodge, Bri-Mathias and Nijssen, Bart and Brancucci, Carlo}, month = jan, year = {2020}, note = {Publisher: IOP Publishing}, pages = {024002}, file = {Full Text:C:\Users\sheikm33\Zotero\storage\UV4N87Q2\Craig et al. - 2020 - Compounding climate change impacts during high str.pdf:application/pdf}, }
(article?){bartos_impacts_2016, title = {Impacts of rising air temperatures on electric transmission ampacity and peak electricity load in the {United} {States}}, volume = {11}, issn = {1748-9326}, url = {https://dx.doi.org/10.1088/1748-9326/11/11/114008}, doi = {10.1088/1748-9326/11/11/114008}, abstract = {Climate change may constrain future electricity supply adequacy by reducing electric transmission capacity and increasing electricity demand. The carrying capacity of electric power cables decreases as ambient air temperatures rise; similarly, during the summer peak period, electricity loads typically increase with hotter air temperatures due to increased air conditioning usage. As atmospheric carbon concentrations increase, higher ambient air temperatures may strain power infrastructure by simultaneously reducing transmission capacity and increasing peak electricity load. We estimate the impacts of rising ambient air temperatures on electric transmission ampacity and peak per-capita electricity load for 121 planning areas in the United States using downscaled global climate model projections. Together, these planning areas account for roughly 80% of current peak summertime load. We estimate climate-attributable capacity reductions to transmission lines by constructing thermal models of representative conductors, then forcing these models with future temperature projections to determine the percent change in rated ampacity. Next, we assess the impact of climate change on electricity load by using historical relationships between ambient temperature and utility-scale summertime peak load to estimate the extent to which climate change will incur additional peak load increases. We find that by mid-century (2040–2060), increases in ambient air temperature may reduce average summertime transmission capacity by 1.9%–5.8% relative to the 1990–2010 reference period. At the same time, peak per-capita summertime loads may rise by 4.2%–15% on average due to increases in ambient air temperature. In the absence of energy efficiency gains, demand-side management programs and transmission infrastructure upgrades, these load increases have the potential to upset current assumptions about future electricity supply adequacy.}, language = {en}, number = {11}, urldate = {2025-07-10}, journal = {Environmental Research Letters}, author = {Bartos, Matthew and Chester, Mikhail and Johnson, Nathan and Gorman, Brandon and Eisenberg, Daniel and Linkov, Igor and Bates, Matthew}, month = nov, year = {2016}, note = {Publisher: IOP Publishing}, pages = {114008}, file = {IOP Full Text PDF:C:\Users\sheikm33\Zotero\storage\IWSMVYQN\Bartos et al. - 2016 - Impacts of rising air temperatures on electric tra.pdf:application/pdf}, }
(article?){henry_differentiating_2019, title = {Differentiating the {Effects} of {Climate} {Change}-{Induced} {Temperature} and {Streamflow} {Changes} on the {Vulnerability} of {Once}-{Through} {Thermoelectric} {Power} {Plants}}, volume = {53}, issn = {0013-936X}, url = {https://doi.org/10.1021/acs.est.8b05718}, doi = {10.1021/acs.est.8b05718}, abstract = {Thermoelectric power plants with once-through cooling systems generated 30% (∼300 GW) of U.S. electricity in 2016. Factors that reduce once-through cooling capacity and thus power output are environmental regulations, warming surface waters, and drought. The latter two may become more frequent as global climate changes. Previous research indicates that reduction in power plant capacity caused by environmental regulations can be significant while that by surface water warming is minor. Here, we address the effect of droughts on power output, which until now has remained conflated with temperature impacts. We do this using a widely used electricity generation model alongside hourly operational and meteorological data for 52 once-through plants located across the U.S. The effect of drought on plant output is examined for different water-availability and temperature scenarios, with and without regulations on plant water discharge. We find that if surface waters warm 3 °C and river discharges drop 20%, droughts would account for ≤20% of total capacity reduction depending on the plant, warming surface waters ≤2.3%, and environmental regulations up to 80%. This suggests that maintaining environmental regulations will require the continued conversion of plant cooling systems from once-through to recirculating, and mitigating climate impacts will require more stringent drought-specific watershed management.}, number = {7}, urldate = {2025-07-10}, journal = {Environmental Science & Technology}, author = {Henry, Candise L. and Pratson, Lincoln F.}, month = apr, year = {2019}, note = {Publisher: American Chemical Society}, pages = {3969–3976}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\XY4GBUQA\Henry and Pratson - 2019 - Differentiating the Effects of Climate Change-Indu.pdf:application/pdf}, }
(article?){plaga_methods_2023, title = {Methods for assessing climate uncertainty in energy system models — {A} systematic literature review}, volume = {331}, issn = {0306-2619}, url = {https://www.sciencedirect.com/science/article/pii/S0306261922016415}, doi = {10.1016/j.apenergy.2022.120384}, abstract = {Due to anthropological climate change, climate scientists project a significant change in climate in the coming years. Despite the advances in climate modeling, future climate is still subject to large uncertainties. To mitigate greenhouse gas emissions and slow down climate change, the energy system must undergo a fundamental transition. Thereby, energy system modeling tools are used to optimize the design of future energy systems. As many components of an energy system depend on climate variables, changing climate and its uncertainties influence the outcome of energy system models. Energy systems with high shares of renewable energies are thereby especially vulnerable to changing climate conditions. To find how the changing climate and its uncertainties are assessed in energy system modeling, a systematic literature review was conducted. Thereby we address three major issues: First, we depict the most common techniques to convert climate data into energy system input data. As large amounts of climate data are necessary to depict future climate developments, we secondly review data reduction techniques which can be used to restrain computational time. Around 46% of the studies in this review use those techniques with scenario building being the most common one. Finally, we review methods to explicitly assess climate uncertainty in energy system models. The majority of energy system optimization models searches for individual solutions for the scenarios, while only 22% use methods that include the uncertainty explicitly in the optimization process. We see the need for further research especially in the use of more advanced optimization methods and the combination of those with well known data reduction techniques. The review provides a wide synopsis of different methods for the three major issues and can therefore enable energy system modelers to choose the right methods for the specific challenges.}, urldate = {2025-07-10}, journal = {Applied Energy}, author = {Plaga, Leonie Sara and Bertsch, Valentin}, month = feb, year = {2023}, keywords = {Climate change, Energy system model, Systematic review, Uncertainty}, pages = {120384}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\F23UZMZN\S0306261922016415.html:text/html}, }
(article?){van_vliet_vulnerability_2012, title = {Vulnerability of {US} and {European} electricity supply to climate change}, volume = {2}, copyright = {2012 Springer Nature Limited}, issn = {1758-6798}, url = {https://www.nature.com/articles/nclimate1546}, doi = {10.1038/nclimate1546}, abstract = {Thermoelectric power in Europe and the United States is vulnerable to climate change. Here research relates lower summer river flows and higher river water temperatures as a result of climate change to thermoelectric plant capacity. Summer average capacity can decrease by 6.3–19% in Europe and 4.4–16% in the United States, depending on the cooling system type and climate scenario for 2031–2060.}, language = {en}, number = {9}, urldate = {2025-07-11}, journal = {Nature Climate Change}, author = {van Vliet, Michelle T. H. and Yearsley, John R. and Ludwig, Fulco and Vögele, Stefan and Lettenmaier, Dennis P. and Kabat, Pavel}, month = sep, year = {2012}, note = {Publisher: Nature Publishing Group}, keywords = {Climate-change impacts, Hydrology}, pages = {676–681}, }
(article?){van_vliet_water_2013, title = {Water constraints on {European} power supply under climate change: impacts on electricity prices}, volume = {8}, issn = {1748-9326}, shorttitle = {Water constraints on {European} power supply under climate change}, url = {https://dx.doi.org/10.1088/1748-9326/8/3/035010}, doi = {10.1088/1748-9326/8/3/035010}, abstract = {Recent warm, dry summers showed the vulnerability of the European power sector to low water availability and high river temperatures. Climate change is likely to impact electricity supply, in terms of both water availability for hydropower generation and cooling water usage for thermoelectric power production. Here, we show the impacts of climate change and changes in water availability and water temperature on European electricity production and prices. Using simulations of daily river flows and water temperatures under future climate (2031–2060) in power production models, we show declines in both thermoelectric and hydropower generating potential for most parts of Europe, except for the most northern countries. Based on changes in power production potentials, we assess the cost-optimal use of power plants for each European country by taking electricity import and export constraints into account. Higher wholesale prices are projected on a mean annual basis for most European countries (except for Sweden and Norway), with strongest increases for Slovenia (12–15%), Bulgaria (21–23%) and Romania (31–32% for 2031–2060), where limitations in water availability mainly affect power plants with low production costs. Considering the long design life of power plant infrastructures, short-term adaptation strategies are highly recommended to prevent undesired distributional and allocative effects.}, language = {en}, number = {3}, urldate = {2025-07-11}, journal = {Environmental Research Letters}, author = {van Vliet, Michelle T H and Vögele, Stefan and Rübbelke, Dirk}, month = jul, year = {2013}, note = {Publisher: IOP Publishing}, pages = {035010}, file = {IOP Full Text PDF:C:\Users\sheikm33\Zotero\storage\PDDHYN8Y\van Vliet et al. - 2013 - Water constraints on European power supply under c.pdf:application/pdf}, }
(article?){hagemann_impact_2011, title = {Impact of a {Statistical} {Bias} {Correction} on the {Projected} {Hydrological} {Changes} {Obtained} from {Three} {GCMs} and {Two} {Hydrology} {Models}}, url = {https://journals.ametsoc.org/view/journals/hydr/12/4/2011jhm1336_1.xml}, doi = {10.1175/2011JHM1336.1}, abstract = {Future climate model scenarios depend crucially on the models’ adequate representation of the hydrological cycle. Within the EU integrated project Water and Global Change (WATCH), special care is taken to use state-of-the-art climate model output for impacts assessments with a suite of hydrological models. This coupling is expected to lead to a better assessment of changes in the hydrological cycle. However, given the systematic errors of climate models, their output is often not directly applicable as input for hydrological models. Thus, the methodology of a statistical bias correction has been developed for correcting climate model output to produce long-term time series with a statistical intensity distribution close to that of the observations. As observations, global reanalyzed daily data of precipitation and temperature were used that were obtained in the WATCH project. Daily time series from three GCMs (GCMs) ECHAM5/Max Planck Institute Ocean Model (MPI-OM), Centre National de Recherches Météorologiques Coupled GCM, version 3 (CNRM-CM3), and the atmospheric component of the L’Institut Pierre-Simon Laplace Coupled Model, version 4 (IPSL CM4) coupled model (called LMDZ-4)—were bias corrected. After the validation of the bias-corrected data, the original and the bias-corrected GCM data were used to force two global hydrology models (GHMs): 1) the hydrological model of the Max Planck Institute for Meteorology (MPI-HM) consisting of the simplified land surface (SL) scheme and the hydrological discharge (HD) model, and 2) the dynamic global vegetation model called LPJmL. The impact of the bias correction on the projected simulated hydrological changes is analyzed, and the simulation results of the two GHMs are compared. Here, the projected changes in 2071–2100 are considered relative to 1961–90. It is shown for both GHMs that the usage of bias-corrected GCM data leads to an improved simulation of river runoff for most catchments. But it is also found that the bias correction has an impact on the climate change signal for specific locations and months, thereby identifying another level of uncertainty in the modeling chain from the GCM to the simulated changes calculated by the GHMs. This uncertainty may be of the same order of magnitude as uncertainty related to the choice of the GCM or GHM. Note that this uncertainty is primarily attached to the GCM and only becomes obvious by applying the statistical bias correction methodology.}, language = {en}, urldate = {2025-07-11}, author = {Hagemann, Stefan and Chen, Cui and Haerter, Jan O. and Heinke, Jens and Gerten, Dieter and Piani, Claudio}, month = aug, year = {2011}, note = {Section: Journal of Hydrometeorology}, keywords = {Bias, Climate models, Hydrologic models, Hydrology, Statistics}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\NFIP37IY\Hagemann et al. - 2011 - Impact of a Statistical Bias Correction on the Pro.pdf:application/pdf}, }
(article?){piani_statistical_2010, title = {Statistical bias correction of global simulated daily precipitation and temperature for the application of hydrological models}, volume = {395}, issn = {0022-1694}, url = {https://www.sciencedirect.com/science/article/pii/S0022169410006475}, doi = {10.1016/j.jhydrol.2010.10.024}, abstract = {A statistical bias correction methodology for global climate simulations is developed and applied to daily land precipitation and mean, minimum and maximum daily land temperatures. The bias correction is based on a fitted histogram equalization function. This function is defined daily, as opposed to earlier published versions in which they were derived yearly or seasonally at best, while conserving properties of robustness and eliminating unrealistic jumps at seasonal or monthly transitions. The methodology is tested using the newly available global dataset of observed hydrological forcing data of the last 50years from the EU project WATCH (WATer and global CHange) and an initial conditions ensemble of simulations performed with the ECHAM5 global climate model for the same period. Bias corrections are derived from 1960 to 1969 observed and simulated data and then applied to 1990–1999 simulations. Results confirm the effectiveness of the methodology for all tested variables. Bias corrections are also derived using three other non-overlapping decades from 1970 to 1999 and all members of the ECHAM5 initial conditions ensemble. A methodology is proposed to use the resulting “ensemble of bias corrections” to quantify the error in simulated scenario projections of components of the hydrological cycle.}, number = {3}, urldate = {2025-07-11}, journal = {Journal of Hydrology}, author = {Piani, C. and Weedon, G. P. and Best, M. and Gomes, S. M. and Viterbo, P. and Hagemann, S. and Haerter, J. O.}, month = dec, year = {2010}, keywords = {Bias correction, Climate projections, Hydrological cycle, Hydrological forcing, Hydrological modeling, Hydrological risk, Water management}, pages = {199–215}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\6HSI6JEA\S0022169410006475.html:text/html}, }
(article?){benestad_climate_2005, title = {Climate change scenarios for northern {Europe} from multi-model {IPCC} {AR4} climate simulations}, volume = {32}, copyright = {Copyright 2005 by the American Geophysical Union.}, issn = {1944-8007}, url = {https://onlinelibrary.wiley.com/doi/abs/10.1029/2005GL023401}, doi = {10.1029/2005GL023401}, abstract = {An empirical-statistical downscaling analysis for monthly mean temperature and precipitation is presented for a multi-model ensemble of the most recent climate scenarios (Special Report Emission Scenario A1b) produced for the upcoming Intergovernmental Panel on Climate Change (IPCC) Assessment Report 4 (AR4). The analysis involves a model evaluation by incorporating common EOF analysis, where the degree of similarity between the spatial structure of large-scale anomalies in re-analysis products and the climate models is examined. The empirical-statistical downscaling incorporates local information for a given set of locations, however, additional geographical information is utilised in the spatial interpolation of the results. A best-estimate of trend is derived through a Bayesian approach. Thus, maps of multi-model mean scenarios for annual mean temperature and precipitation rates for the 21st century are obtained. Positive trends are found in both temperature and precipitation over northern Europe.}, language = {en}, number = {17}, urldate = {2025-07-11}, journal = {Geophysical Research Letters}, author = {Benestad, R. E.}, year = {2005}, note = {_eprint: https://agupubs.onlinelibrary.wiley.com/doi/pdf/10.1029/2005GL023401}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\YSZBISJH\Benestad - 2005 - Climate change scenarios for northern Europe from .pdf:application/pdf;Snapshot:C:\Users\sheikm33\Zotero\storage\MJR6CANS\2005GL023401.html:text/html}, }
(article?){klein_susceptibility_2013, title = {Susceptibility of the {European} electricity sector to climate change}, volume = {59}, issn = {0360-5442}, url = {https://www.sciencedirect.com/science/article/pii/S0360544213005471}, doi = {10.1016/j.energy.2013.06.048}, abstract = {The electricity system is particularly susceptible to climate change due to the close interconnectedness between electricity production, consumption and climate. This study provides a country based relative analysis of 21 European countries’ electricity system susceptibility to climate change. Taking into account 14 quantitative influencing factors, the susceptibility of each country is examined both for the current and projected system with the result being a relative ranked index. Luxembourg and Greece are the most susceptible relatively due in part to their inability to meet their own electricity consumption demand with inland production, and the fact that the majority of their production is from more susceptible sources, primarily combustible fuels. Greece experiences relatively warm mean temperatures, which are expected to increase in the future leading to greater summer electricity consumption, increasing susceptibility. Norway was found to be the least susceptible, relatively, due to its consistent production surplus, which is primarily from hydro (a less susceptible source) and a likely decrease of winter electricity consumption as temperatures rise due to climate change. The findings of this study enable countries to identify the main factors that increase their electricity system susceptibility and proceed with adaptation measures that are the most effective in decreasing susceptibility.}, urldate = {2025-07-11}, journal = {Energy}, author = {Klein, Daniel R. and Olonscheck, Mady and Walther, Carsten and Kropp, Jürgen P.}, month = sep, year = {2013}, keywords = {Air conditioners, Electricity generation by source, Energy security, Heating and cooling electricity consumption, Thermal electricity production, Vulnerability}, pages = {183–193}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\IJLKHNKA\S0360544213005471.html:text/html;Submitted Version:C:\Users\sheikm33\Zotero\storage\LGUPCZM4\Klein et al. - 2013 - Susceptibility of the European electricity sector .pdf:application/pdf}, }
(article?){widmann_statistical_2003, title = {Statistical {Precipitation} {Downscaling} over the {Northwestern} {United} {States} {Using} {Numerically} {Simulated} {Precipitation} as a {Predictor}}, issn = {1520-0442}, url = {https://journals.ametsoc.org/view/journals/clim/16/5/1520-0442_2003_016_0799_spdotn_2.0.co_2.xml}, abstract = {This study investigates whether GCM-simulated precipitation is a good predictor for regional precipitation over Washington and Oregon. In order to allow for a detailed comparison of the estimated precipitation with observations, the simulated precipitation is taken from the NCEP–NCAR reanalysis, which nearly perfectly represents the historic pressure, temperature, and humidity, but calculates precipitation according to the model physics and parameterizations. Three statistical downscaling methods are investigated: (i) local rescaling of the simulated precipitation, and two newly developed methods, namely, (ii) downscaling using singular value decomposition (SVD) with simulated precipitation as the predictor, and (iii) local rescaling with a dynamical correction. Both local scaling methods are straightforward to apply to GCMs that are used for climate change experiments and seasonal forecasts, since they only need control runs for model fitting. The SVD method requires for model fitting special reanalysis-type GCM runs nudged toward observations from a historical period (selection of analogs from the GCM chosen to optimally match the historical weather states might achieve similar results). The precipitation-based methods are compared with conventional statistical downscaling using SVD with various large-scale predictors such as geopotential height, temperature, and humidity. The skill of the different methods for reconstructing historical wintertime precipitation (1958–94) over Oregon and Washington is tested on various spatial scales as small as 50 km and on temporal scales from months to decades. All methods using precipitation as a predictor perform considerably better than the conventional downscaling. The best results using conventional methods are obtained with geopotential height at 1000 hPa or humidity at 850 hPa as predictors. In these cases correlations of monthly observed and reconstructed precipitation on the 50-km scale range from 0.43 to 0.65. The inclusion of several predictor fields does not improve the reconstructions, since they are all highly correlated. Local rescaling of simulated precipitation yields much higher correlations between 0.7 and 0.9, with the exception of the rain shadow of the Cascade Mountains in the Columbia Basin (eastern Washington). When the simulated precipitation is used as a predictor in SVD-based downscaling correlations also reach 0.7 in eastern Washington. Dynamical correction improves the local scaling considerably in the rain shadow and yields correlations almost as high as with the SVD method. Its combination of high skill and ease to use make it particularly attractive for GCM precipitation downscaling.}, language = {en}, urldate = {2025-07-11}, author = {Widmann, Martin and Bretherton, Christopher S. and Salathé, Eric P.}, month = mar, year = {2003}, note = {Section: Journal of Climate}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\HZMFFRR4\Widmann et al. - 2003 - Statistical Precipitation Downscaling over the Nor.pdf:application/pdf}, }
(article?){wilby_sdsm_2002, title = {sdsm — a decision support tool for the assessment of regional climate change impacts}, volume = {17}, issn = {1364-8152}, url = {https://www.sciencedirect.com/science/article/pii/S1364815201000603}, doi = {10.1016/S1364-8152(01)00060-3}, abstract = {General Circulation Models (GCMs) suggest that rising concentrations of greenhouse gases will have significant implications for climate at global and regional scales. Less certain is the extent to which meteorological processes at individual sites will be affected. So-called ‘downscaling’ techniques are used to bridge the spatial and temporal resolution gaps between what climate modellers are currently able to provide and what impact assessors require. This paper describes a decision support tool for assessing local climate change impacts using a robust statistical downscaling technique. Statistical DownScaling Model (sdsm) facilitates the rapid development of multiple, low-cost, single-site scenarios of daily surface weather variables under current and future regional climate forcing. Additionally, the software performs ancillary tasks of predictor variable pre-screening, model calibration, basic diagnostic testing, statistical analyses and graphing of climate data. The application of sdsm is demonstrated with respect to the generation of daily temperature and precipitation scenarios for Toronto, Canada by 2040–2069.}, number = {2}, urldate = {2025-07-11}, journal = {Environmental Modelling & Software}, author = {Wilby, R. L and Dawson, C. W and Barrow, E. M}, month = jan, year = {2002}, keywords = {Canada, Climate change, Downscaling, General circulation models, Scenario}, pages = {145–157}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\Y649XHC5\S1364815201000603.html:text/html}, }
(article?){shrestha_impact_2014, title = {Impact of {Climate} {Change} on {River} {Flow} and {Hydropower} {Production} in {Kulekhani} {Hydropower} {Project} of {Nepal}}, volume = {1}, issn = {2198-7505}, url = {https://doi.org/10.1007/s40710-014-0020-z}, doi = {10.1007/s40710-014-0020-z}, abstract = {This study aims to quantify changes in discharge in the rivers of the Kulekhani watershed due to climate change and examine its future impact on power generation from the Kulekhani Hydropower project. The future climate conditions of the watershed are predicted by downscaling the outputs of A2 and B2 scenarios of the HadCM3 global circulation model for three time periods: 2010–2039, 2040–2069 and 2070–2099 (2020s, 2050s, and 2080s, respectively). The major change in temperature is predicted for 2080s for the A2 scenario, as the maximum and minimum temperatures are predicted to be increased by 1.5 °C and 2.8 °C, respectively. However, the average precipitation of the watershed is expected to decrease in all future time periods. HEC-HMS hydrological model is used to simulate the river discharges during baseline and future periods in the watershed. A decrease in discharge during the wet months (May to September) and an increase during the dry months (October to April) is projected in future time periods against the baseline period for both scenarios. Reservoir simulation is performed using HEC-ResSim in order to analyze the future change in power generation for different operating time settings. Assuming that the hydropower plant operates for 7 h/day during the baseline period (1982–2009), the average power production is expected to decrease by at least 30 % for both A2 and B2 scenarios in the future. Least reduction in power generation (8–13 %), against the baseline period, is observed when the reservoir is operated for 10 h/day in the dry months and 3 h/day in the wet months. The study provides information regarding the climate change impact on Kulekhani hydropower and will assist in planning new hydropower projects.}, language = {en}, number = {3}, urldate = {2025-07-11}, journal = {Environmental Processes}, author = {Shrestha, Sangam and Khatiwada, Medha and Babel, Mukand S. and Parajuli, Kshitij}, month = sep, year = {2014}, keywords = {Climate and Earth System Modelling, Climate change, Climate Sciences, Climate-Change Impacts, Drought, Flooding, HEC-HMS, Hydroenergy, Hydrology, Kulekhani hydropower project, Nepal}, pages = {231–250}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\ESYP38SG\Shrestha et al. - 2014 - Impact of Climate Change on River Flow and Hydropo.pdf:application/pdf}, }
(article?){haguma_optimal_2014-1, title = {Optimal {Hydropower} {Generation} {Under} {Climate} {Change} {Conditions} for a {Northern} {Water} {Resources} {System}}, volume = {28}, issn = {1573-1650}, url = {https://doi.org/10.1007/s11269-014-0763-3}, doi = {10.1007/s11269-014-0763-3}, abstract = {This paper examines climate change impacts on the water resources system of the Manicouagan River (Québec, Canada). The objective is to evaluate the performance of existing infrastructures under future climate projections and the associated uncertainties. The main purpose of the water resources system is hydropower production. A reservoir optimization algorithm, Sampling Stochastic Dynamic Programming (SSDP), was used to derive weekly operating decisions for the existing system subject to reservoir inflows reflecting future climate, for optimum hydropower production. These projections are simulations from the SWAT hydrologic model for climate change scenarios for the period from 2010 to 2099. Results show that the climate change will alter the hydrological regime of the study area: earlier timing of the spring flood, reduced spring peak flow, and increased annual inflows volume in the future compared to the historical climate. The SSDP optimization algorithm adapted the operating policy to the future hydrological regime by adjusting water reservoir levels in the winter and spring, and increasing the release through turbines, which in the end increased power generation. However, there could be more unproductive spills for some power plants, which would decrease the overall efficiency of the existing water resources system.}, language = {en}, number = {13}, urldate = {2025-07-11}, journal = {Water Resources Management}, author = {Haguma, Didier and Leconte, Robert and Côté, Pascal and Krau, Stéphane and Brissette, François}, month = oct, year = {2014}, keywords = {Climate change, Climate-Change Adaptation, Drought, Hydroenergy, Hydrologic regime, Operating policy, Renewable Energy, Water Industry and Water Technology, Water Policy, Water resources system}, pages = {4631–4644}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\HY5L7KCG\Haguma et al. - 2014 - Optimal Hydropower Generation Under Climate Change.pdf:application/pdf}, }
(article?){haylock_european_2008, title = {A {European} daily high-resolution gridded data set of surface temperature and precipitation for 1950–2006}, volume = {113}, copyright = {Copyright 2008 by the American Geophysical Union.}, issn = {2156-2202}, url = {https://onlinelibrary.wiley.com/doi/abs/10.1029/2008JD010201}, doi = {10.1029/2008JD010201}, abstract = {We present a European land-only daily high-resolution gridded data set for precipitation and minimum, maximum, and mean surface temperature for the period 1950–2006. This data set improves on previous products in its spatial resolution and extent, time period, number of contributing stations, and attention to finding the most appropriate method for spatial interpolation of daily climate observations. The gridded data are delivered on four spatial resolutions to match the grids used in previous products as well as many of the rotated pole Regional Climate Models (RCMs) currently in use. Each data set has been designed to provide the best estimate of grid box averages rather than point values to enable direct comparison with RCMs. We employ a three-step process of interpolation, by first interpolating the monthly precipitation totals and monthly mean temperature using three-dimensional thin-plate splines, then interpolating the daily anomalies using indicator and universal kriging for precipitation and kriging with an external drift for temperature, then combining the monthly and daily estimates. Interpolation uncertainty is quantified by the provision of daily standard errors for every grid square. The daily uncertainty averaged across the entire region is shown to be largely dependent on the season and number of contributing observations. We examine the effect that interpolation has on the magnitude of the extremes in the observations by calculating areal reduction factors for daily maximum temperature and precipitation events with return periods up to 10 years.}, language = {en}, number = {D20}, urldate = {2025-07-11}, journal = {Journal of Geophysical Research: Atmospheres}, author = {Haylock, M. R. and Hofstra, N. and Klein Tank, A. M. G. and Klok, E. J. and Jones, P. D. and New, M.}, year = {2008}, note = {_eprint: https://agupubs.onlinelibrary.wiley.com/doi/pdf/10.1029/2008JD010201}, keywords = {Europe, kriging, observation, precipitation, temperature}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\F6FHZFKZ\Haylock et al. - 2008 - A European daily high-resolution gridded data set .pdf:application/pdf;Snapshot:C:\Users\sheikm33\Zotero\storage\SECUB5UJ\2008JD010201.html:text/html}, }
(article?){totschnig_climate_2017, title = {Climate change impact and resilience in the electricity sector: {The} example of {Austria} and {Germany}}, volume = {103}, issn = {0301-4215}, shorttitle = {Climate change impact and resilience in the electricity sector}, url = {https://www.sciencedirect.com/science/article/pii/S0301421517300216}, doi = {10.1016/j.enpol.2017.01.019}, abstract = {The purpose of this paper is to investigate the resilience of possible future electricity and heating systems in regard to climate change and fuel price shocks. The dynamical simulation model HiREPS of the Austrian and German electricity, heating and cooling sectors was used for this analysis. The electricity generation cost and changes in the required secured capacity were used as indicators for the resilience of the energy system. The results show, that the analysed changes in the natural gas price have larger impact on the electricity generation cost than weather variability between different years or climate change. Especially the fossil fuel based scenario showed high sensitivity to the gas price. Analysis of the required secured capacity shows, that in the last quarter of the 21st century the annual maximum residual loads are growing and are dominated by strong cooling demand peaks. Promoting passive cooling options, efficient building designs and options for a controlled down regulation of cooling devices seems to be advisable to avoid installing large thermal power plant backup capacities. The evaluated climate model simulations show only small changes in photovoltaic, wind and hydro power generation for 2051−2080 in Austria and Germany.}, urldate = {2025-07-11}, journal = {Energy Policy}, author = {Totschnig, G. and Hirner, R. and Müller, A. and Kranzl, L. and Hummel, M. and Nachtnebel, H. -P. and Stanzel, P. and Schicker, I. and Formayer, H.}, month = apr, year = {2017}, keywords = {Climate change, Cooling, Electricity, Fuel price shocks, Heating, Resilience}, pages = {238–248}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\DE55A4L8\S0301421517300216.html:text/html}, }
(article?){hempel_trend-preserving_2013, title = {A trend-preserving bias correction &ndash; the {ISI}-{MIP} approach}, volume = {4}, issn = {2190-4979}, url = {https://esd.copernicus.org/articles/4/219/2013/}, doi = {10.5194/esd-4-219-2013}, abstract = {Statistical bias correction is commonly applied within climate impact modelling to correct climate model data for systematic deviations of the simulated historical data from observations. Methods are based on transfer functions generated to map the distribution of the simulated historical data to that of the observations. Those are subsequently applied to correct the future projections. Here, we present the bias correction method that was developed within ISI-MIP, the first Inter-Sectoral Impact Model Intercomparison Project. ISI-MIP is designed to synthesise impact projections in the agriculture, water, biome, health, and infrastructure sectors at different levels of global warming. Bias-corrected climate data that are used as input for the impact simulations could be only provided over land areas. To ensure consistency with the global (land + ocean) temperature information the bias correction method has to preserve the warming signal. Here we present the applied method that preserves the absolute changes in monthly temperature, and relative changes in monthly values of precipitation and the other variables needed for ISI-MIP. The proposed methodology represents a modification of the transfer function approach applied in the Water Model Intercomparison Project (Water-MIP). Correction of the monthly mean is followed by correction of the daily variability about the monthly mean. Besides the general idea and technical details of the ISI-MIP method, we show and discuss the potential and limitations of the applied bias correction. In particular, while the trend and the long-term mean are well represented, limitations with regards to the adjustment of the variability persist which may affect, e.g. small scale features or extremes.}, language = {English}, number = {2}, urldate = {2025-07-11}, journal = {Earth System Dynamics}, author = {Hempel, S. and Frieler, K. and Warszawski, L. and Schewe, J. and Piontek, F.}, month = jul, year = {2013}, note = {Publisher: Copernicus GmbH}, pages = {219–236}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\KWTCRHHJ\Hempel et al. - 2013 - A trend-preserving bias correction &ndash; the ISI.pdf:application/pdf}, }
(article?){ali_projected_2018, title = {Projected {Increase} in {Hydropower} {Production} in {India} under {Climate} {Change}}, volume = {8}, copyright = {2018 The Author(s)}, issn = {2045-2322}, url = {https://www.nature.com/articles/s41598-018-30489-4}, doi = {10.1038/s41598-018-30489-4}, abstract = {Hydropower is a valuable renewable energy resource in India, which can help in climate change mitigation and meet the increasing energy demands. However, the crucial role of climate change on hydropower production in India remains unexplored. Here using the observations and model simulations, we show that seven large hydropower projects experienced a significant (p-value {} 0.05) warming and a decline in precipitation and streamflow during the observed period of 1951–2007. However, all the hydropower projects are projected to experience a warmer and wetter climate in the future. Multimodel ensemble mean annual average temperature (precipitation) is projected to rise up to 6.3 ± 1.6 °C (18 ± 14.6%) in the catchments upstream of the other reservoirs by the end of the 21st century under representative concentration pathway (RCP) 8.5. Due to the projected increase in precipitation, mean annual streamflow (up to +45%) and hydropower (up to +25%) production are projected to rise under the future climate. However, significant warming (6.25 ± 1.62 °C) is projected to result in a decline in streamflow and hydropower production in May- June for snow-dominated Nathpa Jhakri and Bhakra Nangal hydropower projects. Our results provide insights into the development and planning of hydropower projects in India under the current projected future climate.}, language = {en}, number = {1}, urldate = {2025-07-11}, journal = {Scientific Reports}, author = {Ali, Syed Azhar and Aadhar, Saran and Shah, Harsh L. and Mishra, Vimal}, month = aug, year = {2018}, note = {Publisher: Nature Publishing Group}, keywords = {Climate sciences, Hydrology}, pages = {12450}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\35W6TKWD\Ali et al. - 2018 - Projected Increase in Hydropower Production in Ind.pdf:application/pdf}, }
(article?){turner_climate_2017, title = {Climate impacts on hydropower and consequences for global electricity supply investment needs}, volume = {141}, issn = {0360-5442}, url = {https://www.sciencedirect.com/science/article/pii/S0360544217319473}, doi = {10.1016/j.energy.2017.11.089}, abstract = {Climate change is projected to increase hydropower generation in some parts of the world and decrease it in others. Here we explore the possible consequences of these impacts for the electricity supply sector at the global scale. Regional hydropower projections are developed by forcing a coupled global hydrological and dam model with downscaled, bias-corrected climate realizations. Consequent impacts on power sector composition and associated emissions and investment costs are explored using the Global Change Assessment Model (GCAM). We find that climate-driven changes in hydropower generation may shift power demands onto and away from carbon intensive technologies. This causes significantly altered power sector CO2 emissions in several hydro-dependent regions, although the net global impact is modest. For drying regions, we estimate a global, cumulative investment need of approximately one trillion dollars (±$500 billion) this century to make up for deteriorated hydropower generation caused by climate change. Total investments avoided are of a similar magnitude across regions projected to experience increased precipitation. Investment risks and opportunities are concentrated in hydro-dependent countries for which significant climate change is expected. Various countries throughout the Balkans, Latin America and Southern Africa are most vulnerable, whilst Norway, Canada, and Bhutan emerge as clear beneficiaries.}, urldate = {2025-07-11}, journal = {Energy}, author = {Turner, Sean W. D. and Hejazi, Mohamad and Kim, Son H. and Clarke, Leon and Edmonds, Jae}, month = dec, year = {2017}, keywords = {Climate change, Electricity, Hydropower, Integrated assessment modeling, Water-energy nexus}, pages = {2081–2090}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\H46XJAPG\S0360544217319473.html:text/html}, }
(article?){mpelasoka_influence_2009, title = {Influence of {Rainfall} {Scenario} {Construction} {Methods} on {Runoff} {Projections}}, url = {https://journals.ametsoc.org/view/journals/hydr/10/5/2009jhm1045_1.xml}, doi = {10.1175/2009JHM1045.1}, abstract = {The future rainfall series used to drive hydrological models in most climate change impact studies is informed by global climate models (GCMs). This paper compares future runoff projections in ∼11 000 0.25° grid cells across Australia from a daily rainfall–runoff model driven with future daily rainfall series obtained using three simple scaling methods, informed by 14 GCMs. In the constant scaling and daily scaling methods, the historical daily rainfall series is scaled by the relative difference between GCM simulations for the future and historical climates. The constant scaling method scales all the daily rainfall by the same factor, and the daily scaling method takes into account changes in the daily rainfall distribution by scaling the different daily rainfall amounts differently. In the daily translation method, the GCM future daily rainfall series is translated to a 0.25° gridcell rainfall series using the relationship established between the historical GCM-scale rainfall and 0.25° gridcell rainfall data. The daily scaling and daily translation methods generally give higher extreme and annual runoff than the constant scaling method because they take into account the increase in extreme daily rainfall (which generates significant runoff) simulated by the large majority of the GCMs. However, the difference between the mean annual runoff simulated with future daily rainfall series obtained using the constant versus daily scaling methods is generally less than 5%, which is relatively smaller than the range of runoff results from the different GCMs of 30%–40%.}, language = {en}, urldate = {2025-07-11}, author = {Mpelasoka, Freddie S. and Chiew, Francis H. S.}, month = oct, year = {2009}, note = {Section: Journal of Hydrometeorology}, keywords = {Australia, Climate change, Rainfall, Runoff}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\RC885S5C\Mpelasoka and Chiew - 2009 - Influence of Rainfall Scenario Construction Method.pdf:application/pdf}, }
(article?){guo_identifying_2020, title = {Identifying how future climate and land use/cover changes impact streamflow in {Xinanjiang} {Basin}, {East} {China}}, volume = {710}, issn = {0048-9697}, url = {https://www.sciencedirect.com/science/article/pii/S0048969719362710}, doi = {10.1016/j.scitotenv.2019.136275}, abstract = {Climate and land use/cover changes are the main factors altering hydrological regimes. To understand the impacts of climate and land use/cover changes on streamflow within a specific catchment, it is essential to accurately quantify their changes given many possibilities. We propose an integrated framework to assess how individual and combined climate and land use/cover changes impact the streamflow of Xinanjiang Basin, in East China, in the future. Five bias-corrected and downscaled General Circulation Model (GCM) projections are used to indicate the inter-model uncertainties under three Representative Concentration Pathways (RCPs). Additionally, three land use/cover change scenarios representing a range of tradeoffs between ecological protection (EP) and urban development (UD) are projected by Cellular Automata - Markov (CA-Markov). The streamflow in 2021–2050 is then assessed using the calibrated Soil and Water Assessment Tool (SWAT) with 15 scenarios and 75 possibilities. Finally, the uncertainty and attribution of streamflow changes to climate and land use/cover changes at monthly and annual scale are analyzed. Results show that while both land use/cover change alone and combined changes project an increase in streamflow, there is a disagreement on the direction of streamflow change under climate change alone. Future streamflow may undergo a more blurred boundary between the flood and non-flood seasons, potentially easing the operation stress of Xinanjiang Reservoir for water supply or hydropower generation. We find that the impacts of climate and land use/cover changes on monthly mean streamflow are sensitive to the impermeable area (IA). The impacts of climate change are stronger than those induced by land use/cover change under EP (i.e., lower IA); and land use/cover change has a greater impact in case of UD (i.e., higher IA). However, changes in annual mean streamflow are mainly driven by land use/cover change, and climate change may decrease the influence attributed to land use/cover change.}, urldate = {2025-07-11}, journal = {Science of The Total Environment}, author = {Guo, Yuxue and Fang, Guohua and Xu, Yue-Ping and Tian, Xin and Xie, Jingkai}, month = mar, year = {2020}, keywords = {Attribution, Climate change, Land use/cover change, Multiple scenarios, Streamflow response, Uncertainty}, pages = {136275}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\64HTFDA5\S0048969719362710.html:text/html}, }
(article?){thrasher_technical_2012, title = {Technical {Note}: {Bias} correcting climate model simulated daily temperature extremes with quantile mapping}, volume = {16}, issn = {1027-5606}, shorttitle = {Technical {Note}}, url = {https://hess.copernicus.org/articles/16/3309/2012/}, doi = {10.5194/hess-16-3309-2012}, abstract = {When applying a quantile mapping-based bias correction to daily temperature extremes simulated by a global climate model (GCM), the transformed values of maximum and minimum temperatures are changed, and the diurnal temperature range (DTR) can become physically unrealistic. While causes are not thoroughly explored, there is a strong relationship between GCM biases in snow albedo feedback during snowmelt and bias correction resulting in unrealistic DTR values. We propose a technique to bias correct DTR, based on comparing observations and GCM historic simulations, and combine that with either bias correcting daily maximum temperatures and calculating daily minimum temperatures or vice versa. By basing the bias correction on a base period of 1961–1980 and validating it during a test period of 1981–1999, we show that bias correcting DTR and maximum daily temperature can produce more accurate estimations of daily temperature extremes while avoiding the pathological cases of unrealistic DTR values.}, language = {English}, number = {9}, urldate = {2025-07-11}, journal = {Hydrology and Earth System Sciences}, author = {Thrasher, B. and Maurer, E. P. and McKellar, C. and Duffy, P. B.}, month = sep, year = {2012}, note = {Publisher: Copernicus GmbH}, pages = {3309–3314}, file = {Full Text PDF:C:\Users\sheikm33\Zotero\storage\IKTMMGKN\Thrasher et al. - 2012 - Technical Note Bias correcting climate model simu.pdf:application/pdf}, }
