(incollection?){shepard_computer_1984, address = {Dordrecht}, title = {Computer {Mapping}: {The} {SYMAP} {Interpolation} {Algorithm}}, isbn = {978-94-017-3048-8}, shorttitle = {Computer {Mapping}}, url = {https://doi.org/10.1007/978-94-017-3048-8_7}, abstract = {A major application of computer mapping is to display levels of some dependent variable over a geographical area. In general, this dependent variable is known only at a limited number of specified locations, henceforth termed “data points,” and must be interpolated for other locations. The need for an interpolation algorithm arises in a great variety of applications. In city, regional and geographical planning, social and economic characteristics (e.g., population density) are known only at the centers of data collection zones (e.g., towns or census tracts). In meteorology and air pollution analysis, atmospheric conditions and pollution concentration are known only at monitoring stations. In geology and oceanography, depths are known only where soundings have been made. In epidemiology, the death rates are known only for some representative point (or as an overall average) for the state or county over which vital statistics have been calculated. The values of the dependent variable to be mapped (subsequently denoted by Z) form a surface over a geographical area in the same way that a relief map represents a topographic surface.}, language = {en}, urldate = {2025-07-11}, booktitle = {Spatial {Statistics} and {Models}}, publisher = {Springer Netherlands}, author = {Shepard, Donald S.}, editor = {Gaile, Gary L. and Willmott, Cort J.}, year = {1984}, doi = {10.1007/978-94-017-3048-8_7}, pages = {133–145}, }
(article?){golombek_climate_2012, title = {Climate change: impacts on electricity markets in {Western} {Europe}}, volume = {113}, issn = {0165-0009}, shorttitle = {Climate change}, doi = {10.1007/s10584-011-0348-6}, abstract = {This paper studies some impacts of climate change on electricity markets, focusing on three climate effects. First, demand for electricity is affected because of changes in the temperature. Second, changes in precipitation and temperature have impact on supply of hydro electric production through a shift in the inflow of water. Third, plant efficiency for thermal generation will decrease because the temperature of water used to cool equipment increases. To find the magnitude of these partial effects, as well as the overall effects, on Western European energy markets, we use the multi-market equilibrium model LIBEMOD. We find that each of the three partial effects changes the average electricity producer price by less than 2%, while the net effect is an increase of only 1%. The partial effects on total electricity supply are small, and the net effect is a decrease of 4%. The greatest effects are found for Nordic countries with a large market share for reservoir hydro. In these countries, annual production of electricity increases by 8%, reflecting more inflow of water, while net exports doubles. In addition, because of lower inflow in summer and higher in winter, the reservoir filling needed to transfer water from summer to winter is drastically reduced in the Nordic countries.}, language = {eng}, number = {2}, journal = {Climatic Change}, author = {Golombek, Rolf and Kittelsen, Sverre A. C. and Haddeland, Ingjerd}, year = {2012}, pmid = {26005231}, pmcid = {PMC4439730}, pages = {357–370}, file = {Full Text:C:\Users\sheikm33\Zotero\storage\MCP5DJUN\Golombek et al. - 2012 - Climate change impacts on electricity markets in .pdf:application/pdf}, }
(article?){boehlert_climate_2016, title = {Climate change impacts and greenhouse gas mitigation effects on {U}.{S}. hydropower generation}, volume = {183}, issn = {0306-2619}, url = {https://www.sciencedirect.com/science/article/pii/S0306261916313563}, doi = {10.1016/j.apenergy.2016.09.054}, abstract = {Climate change will have potentially significant effects on hydropower generation due to changes in the magnitude and seasonality of river runoff and increases in reservoir evaporation. These physical impacts will in turn have economic consequences through both producer revenues and consumer expenditures. We analyze the physical and economic effects of changes in hydropower generation for the contiguous U.S. in futures with and without global-scale greenhouse gas (GHG) mitigation, and across patterns from 18 General Circulation Models. Using a monthly water resources systems model of 2119 river basins that routes simulated river runoff through reservoirs, and allocates water to potentially conflicting and climate dependent demands, we provide a first-order estimate of the impacts of various projected emissions outcomes on hydropower generation, and monetize these impacts using outputs from an electric sector planning model for over 500 of the largest U.S. hydropower facilities. We find that, due to generally increasing river runoff under higher emissions scenarios in the Pacific Northwest, climate change tends to increase overall hydropower generation in the contiguous U.S. During low flow months, generation tends to fall with increasing emissions, potentially threatening the estimated low flow, firm energy from hydropower. Although global GHG mitigation slows the growth in hydropower generation, the higher value placed on carbon-free hydropower leads to annual economic benefits ranging from $1.8 billion to $4.3 billion. The present value of these benefits to the U.S. from global greenhouse gas mitigation, discounted at 3%, is $34 to $45 billion over the 2015–2050 period.}, urldate = {2025-07-11}, journal = {Applied Energy}, author = {Boehlert, Brent and Strzepek, Kenneth M. and Gebretsadik, Yohannes and Swanson, Richard and McCluskey, Alyssa and Neumann, James E. and McFarland, James and Martinich, Jeremy}, month = dec, year = {2016}, keywords = {Climate change, Economic impacts, Energy, Greenhouse gases, Hydropower, Mitigation}, pages = {1511–1519}, file = {ScienceDirect Snapshot:C:\Users\sheikm33\Zotero\storage\NI2N3FFW\S0306261916313563.html:text/html}, }
